import{_ as e,o as t,c as a,a4 as p}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"“人工智能+农机农艺融合”中试验证、熟化应用推进“三新”大规模应用对话会在乌鲁木齐成功召开","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"“人工智能+农机农艺融合”中试验证、熟化应用推进“三新”大规模应用对话会在乌鲁木齐成功召开","date":"2026-06-20T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260616_6485018.htm","summary":"5月25日,2026新疆国际农业机械博览会在乌鲁木齐举办期间,中国农业机械流通协会、中国农业机械化协会、中国农业机械工业协会联合组织召开了“人工智能+农机农艺融合”中试验证、熟化应用推进“三新”(新技术、新产品、新场景)大规模应用对话会。...\\n","contentHash":"9786086064d5adc75583d793b476c989","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-06-20-人工智能-农机农艺融合-中试验证-熟化应用推进-三新-大规模应用对话会在乌鲁木齐成功召开.md","filePath":"news/2026-06-20-人工智能-农机农艺融合-中试验证-熟化应用推进-三新-大规模应用对话会在乌鲁木齐成功召开.md"}'),r={name:"news/2026-06-20-人工智能-农机农艺融合-中试验证-熟化应用推进-三新-大规模应用对话会在乌鲁木齐成功召开.md"};function n(s,_,o,l,d,c){return t(),a("div",null,[..._[0]||(_[0]=[p('<h1 id="人工智能-农机农艺融合-中试验证、熟化应用推进-三新-大规模应用对话会在乌鲁木齐成功召开" tabindex="-1">“人工智能+农机农艺融合”中试验证、熟化应用推进“三新”大规模应用对话会在乌鲁木齐成功召开 <a class="header-anchor" href="#人工智能-农机农艺融合-中试验证、熟化应用推进-三新-大规模应用对话会在乌鲁木齐成功召开" aria-label="Permalink to &quot;“人工智能+农机农艺融合”中试验证、熟化应用推进“三新”大规模应用对话会在乌鲁木齐成功召开&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260616_6485018.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-06-20 摘要: 5月25日,2026新疆国际农业机械博览会在乌鲁木齐举办期间,中国农业机械流通协会、中国农业机械化协会、中国农业机械工业协会联合组织召开了“人工智能+农机农艺融合”中试验证、熟化应用推进“三新”(新技术、新产品、新场景)大规模应用对话会。...</p></blockquote><p>农业农村部农业机械化总站副站长刘小伟、中国农业机械流通协会会长范建华、中国农业机械化协会副会长刘恒新、中国农业机械工业协会副会长李有吉和中国农学会学术交流处赵阳佳等嘉宾出席会议并发言。</p><p>“四位一体”破解农机“三新”推广难题</p><p>会上,由中国农业机械流通协会智慧农业产教融合专委会秘书长潘超介绍了协会基于部级基地——农业农村部作物栽培与机械化现代农业科技试验示范基地(内黄)推出的“人工智能+机艺融合”中试验证、熟化应用系列工作。该系列工作构建了“四位一体”的解决方案,很好地回答了“推广什么、怎么推广、谁来推广”的核心问题。</p><p>一是出具《中试验证报告》,为好农机做权威背书。依托农业农村部首批、河南省唯一的“作物栽培与机械化现代农业科技试验示范基地”,流通协会通过真实生产场景中的多维度、全生育期数据采集,为优质农机产品出具权威《中试验证报告》,用数据为产品的技术表现、农艺适配性、经济效益提供立体化证明,解决“效果难量化、溢价无支撑”的行业难题。该基地已在盐碱沙地上实现小麦—玉米“吨半粮”,2024年玉米实收亩产854.8公斤,2025年小麦实收亩产632.4公斤,分别较周边农户增产24.5%和19.9%,同时收获强筋一等小麦和低毒素玉米,实现品质与效益的双提升。</p><p>二是实现“农机+数字农艺”最佳性能的产品组合封装。流通协会帮助企业将农机产品与AI算法、属地农艺深度融合,形成可量化、可验证的数字化产品包,将分散的技术成果转化为系统性的可复制方案。目前已在精准施肥、智能灌溉、变量作业等八大环节形成标准化的服务产品包。</p><p>三是制定“合作社—农服方案—地块”三位一体匹配机制。基于“1+6+28+N”推广体系(1个部级基地联动6个省级基地,带动28个农机合作社,串联N家企业),流通协会将农服方案与合作社能力对应、将地块需求与农服方案匹配,实现了技术从“盆景”到“风景”的跨越。</p><p>四是培育数字农服组织,赋能经销商转型。流通协会系统培育县域新型数字农服组织,帮助农机经销商从传统的“卖产品”向提供“按种植效果收费”的数字农服转型,成为连接技术、企业与农户的关键纽带,实现“保底收益+增值分成”的共赢模式。</p><p>推动熟化应用是“高速路”建设</p><p>与会代表一致认为,在智慧农业时代,农机行业正从卖单品向卖方案升级。中试验证是农机产品数字化时代的“入场券”,熟化应用则是技术走向市场的“高速路”,而数据底座是构建产业生态的“新基建”。</p><p>会上,北京大蚯蚓科技李迅博士详细介绍了内黄基地可提供的数字化底座支撑;北大荒农服集团副总经理吴殿勇分享了未来农场实践,验证了“人工智能+机艺融合”在大型规模化种植场景中的降本增效价值——亩均节肥5%、节药27%、增产9%,亩均节本增收80元;武汉禾大科技副总经理王育新介绍了“水肥药+X”一体化服务方案,计划依托内黄基地开展中试验证,目标是实现节氮15%以上、增产8%以上;亩祖里农业机械(中国)SKD工厂厂长喻雷围绕“产品+数字农艺封装”目标,提出了通过中试验证获取高价值权威背书的具体需求;江西宜丰县通达农机农民专业合作社董事长漆润新以“深耕农机五十载”的亲身经历,讲述了从产品经销到数字化服务的三次跨越,为行业转型提供了鲜活的基层样本。</p><p>做实中试、做深熟化、做优生态</p><p>刘小伟对协会系列工作给予充分肯定,他指出,协会推出的《中试验证报告》、产品组合封装、“1+6+28+N”推广体系、三位一体匹配机制以及数字农服组织培育等举措,“精准回应了‘推广什么、怎么推广、谁来推广’三大痛点,搭建起了科技转化跨越‘死亡之谷’的桥梁”。他呼吁各级农机推广部门、制造企业、经销商、合作社和科研院所拧成一股绳,共同推进“人工智能+机艺融合”中试验证、熟化应用行业协作工作落地生根。</p><p>刘恒新指出,本次对话会“主题突出、靶向精准,是践行国家‘加强农业数智化转型升级’部署的生动实践”。中国农业机械工业协会副会长李有吉表示,中试验证为农机提供了标准化的田间验证体系,“是产品大规模应用的前提”。另据赵阳佳介绍,内黄基地“人工智能+农机农艺融合”应用场景已入选2025年中国农业重大科技新成果“新场景”,成为首个获此称号的“新场景”成果。</p><p>范建华在总结讲话中表示,本次对话会达成了三项核心共识:中试验证是数字化时代产品的“入场券”,熟化应用是技术走向市场的“高速路”,数据底座是产业生态的“新基建”。他表示,流通协会下一步将全力做好三件事:做实中试验证,欢迎更多企业将产品拿到部级基地进行权威验证;做深熟化应用,依托“1+6+28+N”体系将验证成功的方案快速推向市场;做优产业生态,推动种、肥、药、械、智慧农业跨行业协同,让“联合起来·把地种好”的愿景变为现实。</p><p>本次对话会还宣布了中国农业机械流通协会智慧农业专委会运营的农业农村部作物栽培与机械化现代农业科技试验示范基地(内黄)将承接农业农村部农业机械化总站6月4日召开的“小麦智能化联合收获技术研讨会”,现场观摩示范基地小麦高质量收获与玉米高质量播种作业,进一步推动“三新”大规模应用落地见效。</p><p>会议还邀请了新疆维吾尔自治区农机行业协会专家委员会主任裴新民、新疆农业大学机电工程学院院长郭俊先等新疆方面的有关专家,北大荒农服集团、北京大蚯蚓数字科技、武汉禾大科技、亩祖里农业机械(北京)等企业代表,新疆农业大学、新疆农机行业协会等区域机构代表进行交流发言。</p><p>本次对话会由中国农业机械流通协会智慧农业产教融合专委会主办,中国农业机械流通协会农业社会化服务分会、中国农业机械流通协会媒体分会、新疆维吾尔自治区农机行业协会、新疆维吾尔自治区农业机械学会、新疆农业大学机电工程学院、新疆智能农业装备重点实验室、石河子大学农学院、农业人工智能与智慧生产重点实验室联合协办。</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260616_6485018.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',20)])])}const h=e(r,[["render",n]]);export{f as __pageData,h as default};
